class Solution {
    bool isVowel(char c) {
        return c=='a'||c=='e'||c=='i'||c=='o'||c=='u'
            || c=='A'||c=='E'||c=='I'||c=='O'||c=='U';
    }
public:
    bool halvesAreAlike(string s) {
        int half = s.size() / 2;
        int countA = 0, countB = 0;
        for (int i = 0; i < half; i++) {
            if (isVowel(s[i])) countA++;
            if (isVowel(s[i + half])) countB++;
        }
        return countA == countB;
    }
};
